\title{Visual Jigsaw Post-Training Improves MLLMs}





\author{Penghao Wu$^{1}$ \quad Yushan Zhang$^{2}$ \quad Haiwen Diao$^{1}$ \quad Bo Li$^{1}$ \quad Lewei Lu$^{3}$ \quad Ziwei Liu$^{1}$ \\[5pt]
